/**
 * Centralized Tauri IPC service layer.
 *
 * This module provides a standardized way to invoke Tauri commands with
 * consistent error handling and normalization. All stores and components
 * should use `safeInvoke` instead of directly calling the Tauri `invoke` API.
 */

import { invoke } from '@tauri-apps/api/core';
import type { NormalizedError, SafeResult } from './errors';

/**
 * Rust CommandError as serialized by Tauri.
 * This matches the TypeScript type generated by tauri-specta.
 */
type CommandError =
  | { DatabaseError: { message: string; error_id: string } }
  | { NotFound: { message: string; error_id: string } }
  | { ValidationError: { fields: Record<string, unknown>; error_id: string } }
  | { PermissionDenied: { message: string; error_id: string } }
  | { Unknown: { message: string; error_id: string } }
  | { BusinessRule: { message: string; error_id: string } }
  | { Conflict: { message: string; error_id: string } };

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function normalizeValidationFields(value: unknown): Record<string, string> {
  if (!isRecord(value)) {
    return {};
  }

  return Object.fromEntries(
    Object.entries(value).map(([field, issue]) => {
      if (typeof issue === 'string') {
        return [field, issue];
      }
      if (Array.isArray(issue)) {
        const messages = issue
          .map((item) =>
            isRecord(item) && typeof item.message === 'string'
              ? item.message
              : isRecord(item) && typeof item.code === 'string'
                ? item.code
                : typeof item === 'string'
                  ? item
                  : null
          )
          .filter((message): message is string => message !== null);
        return [field, messages.length > 0 ? messages.join('; ') : 'Invalid value'];
      }
      if (isRecord(issue) && typeof issue.message === 'string') {
        return [field, issue.message];
      }
      if (isRecord(issue) && typeof issue.code === 'string') {
        return [field, issue.code];
      }
      return [field, 'Invalid value'];
    })
  );
}

/**
 * Normalize a Rust CommandError into our application's NormalizedError format.
 *
 * @param error - The error from Rust (CommandError) or a JavaScript Error
 * @returns A normalized error object
 */
export function normalizeError(error: unknown): NormalizedError {
  // Handle Rust CommandError (tagged union)
  if (error && typeof error === 'object') {
    const err = error as Partial<CommandError>;

    if ('DatabaseError' in err && typeof err.DatabaseError === 'string') {
      return {
        kind: 'database',
        message: err.DatabaseError
      };
    }

    if (
      'DatabaseError' in err &&
      err.DatabaseError !== null &&
      typeof err.DatabaseError === 'object'
    ) {
      return {
        kind: 'database',
        message:
          typeof err.DatabaseError.message === 'string'
            ? err.DatabaseError.message
            : 'Database error occurred',
        errorId:
          typeof err.DatabaseError.error_id === 'string' ? err.DatabaseError.error_id : undefined
      };
    }

    if ('NotFound' in err && typeof err.NotFound === 'string') {
      return {
        kind: 'not_found',
        message: err.NotFound
      };
    }

    if ('NotFound' in err && err.NotFound !== null && typeof err.NotFound === 'object') {
      return {
        kind: 'not_found',
        message:
          typeof err.NotFound.message === 'string' ? err.NotFound.message : 'Resource not found',
        errorId: typeof err.NotFound.error_id === 'string' ? err.NotFound.error_id : undefined
      };
    }

    if (
      'ValidationError' in err &&
      err.ValidationError !== null &&
      typeof err.ValidationError === 'object'
    ) {
      return {
        kind: 'validation',
        message: 'Validation failed',
        fields: normalizeValidationFields(
          isRecord(err.ValidationError.fields) ? err.ValidationError.fields : err.ValidationError
        ),
        errorId:
          typeof err.ValidationError.error_id === 'string'
            ? err.ValidationError.error_id
            : undefined
      };
    }

    if (
      'PermissionDenied' in err &&
      err.PermissionDenied !== null &&
      typeof err.PermissionDenied === 'object'
    ) {
      return {
        kind: 'permission_denied',
        message:
          typeof err.PermissionDenied.message === 'string'
            ? err.PermissionDenied.message
            : 'Permission denied',
        errorId:
          typeof err.PermissionDenied.error_id === 'string'
            ? err.PermissionDenied.error_id
            : undefined
      };
    }

    if ('PermissionDenied' in err && typeof err.PermissionDenied === 'string') {
      return {
        kind: 'permission_denied',
        message: err.PermissionDenied
      };
    }

    if ('Unknown' in err) {
      const unknown = err.Unknown;

      if (typeof unknown === 'string') {
        return {
          kind: 'unknown',
          message: unknown
        };
      }

      if (unknown !== null && typeof unknown === 'object') {
        const unknownObject = unknown as { message?: string; error_id?: string };
        return {
          kind: 'unknown',
          message:
            typeof unknownObject.message === 'string'
              ? unknownObject.message
              : 'An unexpected error occurred',
          ...(typeof unknownObject.error_id === 'string' ? { errorId: unknownObject.error_id } : {})
        };
      }
    }

    if ('BusinessRule' in err) {
      if (typeof err.BusinessRule === 'string') {
        return { kind: 'unknown', message: err.BusinessRule };
      }
      if (err.BusinessRule !== null && typeof err.BusinessRule === 'object') {
        return {
          kind: 'unknown',
          message:
            typeof err.BusinessRule.message === 'string'
              ? err.BusinessRule.message
              : 'Business rule violation',
          ...(typeof err.BusinessRule.error_id === 'string'
            ? { errorId: err.BusinessRule.error_id }
            : {})
        };
      }
    }

    if ('Conflict' in err) {
      if (typeof err.Conflict === 'string') {
        return { kind: 'unknown', message: err.Conflict };
      }
      if (err.Conflict !== null && typeof err.Conflict === 'object') {
        return {
          kind: 'unknown',
          message:
            typeof err.Conflict.message === 'string' ? err.Conflict.message : 'Data conflict',
          ...(typeof err.Conflict.error_id === 'string' ? { errorId: err.Conflict.error_id } : {})
        };
      }
    }

    if (
      'BusinessRule' in err &&
      err.BusinessRule !== null &&
      typeof err.BusinessRule === 'object'
    ) {
      return {
        kind: 'unknown',
        message:
          typeof err.BusinessRule.message === 'string'
            ? err.BusinessRule.message
            : 'Business rule violation',
        errorId:
          typeof err.BusinessRule.error_id === 'string' ? err.BusinessRule.error_id : undefined
      };
    }

    if ('Conflict' in err && err.Conflict !== null && typeof err.Conflict === 'object') {
      return {
        kind: 'unknown',
        message: typeof err.Conflict.message === 'string' ? err.Conflict.message : 'Data conflict',
        errorId: typeof err.Conflict.error_id === 'string' ? err.Conflict.error_id : undefined
      };
    }
  }

  // Handle JavaScript Error objects
  if (error instanceof Error) {
    return {
      kind: 'unknown',
      message: error.message || 'An unexpected error occurred'
    };
  }

  // Fallback for completely unknown error types
  return {
    kind: 'unknown',
    message: String(error) || 'An unexpected error occurred'
  };
}

/**
 * Safely invoke a Tauri command with normalized error handling.
 *
 * This function wraps the raw Tauri `invoke` API and provides:
 * - Consistent error shape across all commands
 * - Automatic error normalization from Rust CommandError
 * - Type-safe return values
 *
 * @template T - The expected return type from the command
 * @param command - The name of the Tauri command to invoke
 * @param args - Arguments to pass to the command
 * @returns A SafeResult containing either the data or a normalized error
 *
 * @example
 * ```typescript
 * const result = await safeInvoke<Wishlist>('get_wishlist_by_id', { id: '123' });
 * if (result.ok) {
 *   console.log('Wishlist:', result.data);
 * } else {
 *   console.error('Error:', result.error.message);
 *   if (isValidationError(result.error)) {
 *     // Handle field-specific validation errors
 *     Object.entries(result.error.fields).forEach(([field, msg]) => {
 *       console.error(`  ${field}: ${msg}`);
 *     });
 *   }
 * }
 * ```
 */
export async function safeInvoke<T>(
  command: string,
  args?: Record<string, unknown>
): Promise<SafeResult<T>> {
  try {
    const data = await invoke<T>(command, args ?? {});
    return { ok: true, data };
  } catch (error) {
    return { ok: false, error: normalizeError(error) };
  }
}

/**
 * Invoke a Tauri command and throw a normalized error on failure.
 *
 * This is useful when you want to use try/catch instead of checking result.ok.
 *
 * @template T - The expected return type from the command
 * @param command - The name of the Tauri command to invoke
 * @param args - Arguments to pass to the command
 * @returns The command result
 * @throws {NormalizedError} If the command fails
 *
 * @example
 * ```typescript
 * try {
 *   const wishlist = await invokeOrThrow<Wishlist>('get_wishlist_by_id', { id: '123' });
 *   console.log('Wishlist:', wishlist);
 * } catch (error) {
 *   if (isNotFoundError(error as NormalizedError)) {
 *     // Handle not found
 *   }
 * }
 * ```
 */
export async function invokeOrThrow<T>(
  command: string,
  args?: Record<string, unknown>
): Promise<T> {
  const result = await safeInvoke<T>(command, args);
  if (!result.ok) {
    throw result.error;
  }
  return result.data;
}
